def verify_f306_evidence() -> None:
    root = CODEX / "evidence/f306-interleaved-coverage-oracle-2026-08-05"
    try:
        raw = json.loads((root / "raw-campaign.json").read_text(encoding="ascii"))
        summary = json.loads((root / "summary.json").read_text(encoding="ascii"))
        readme = (root / "README.md").read_text(encoding="ascii")
        manifest = (root / "SHA256SUMS.txt").read_text(encoding="ascii").splitlines()
        manifest_paths: set[str] = set()
        mismatches: list[str] = []
        for line in manifest:
            expected, relative = line.split("  ", 1)
            if relative in manifest_paths:
                mismatches.append(f"duplicate:{relative}")
                continue
            manifest_paths.add(relative)
            actual = hashlib.sha256((root / relative).read_bytes()).hexdigest()
            if actual != expected:
                mismatches.append(relative)
        check(
            not mismatches
            and manifest_paths
            == {
                "README.md",
                "raw-campaign.json",
                "summary.json",
            },
            "F306 evidence files match the complete SHA-256 manifest",
        )

        fixed_hashes = {
            "afl_binary_sha256": (
                "68269c89d36da5046f1de0531ddab8b06775c4518f5272ff0aaeae5a24dd7e2f"
            ),
            "seed_sha256": (
                "b97f4b93891b87eae9974d4922628b4cbd47cff79350a09253489acfcc10db33"
            ),
            "showmap_binary_sha256": (
                "feedfc2f5b2825fd7badeb098aa8b25c1857dc3e3afe8159688786997833791b"
            ),
        }
        check(
            raw.get("schema") == "symcc-qa3-interleaved-coverage-campaign-v1"
            and summary.get("schema") == "symcc-qa3-interleaved-coverage-summary-v1"
            and all(
                raw.get(key) == value and summary.get(key) == value
                for key, value in fixed_hashes.items()
            ),
            "F306 schemas and target/seed/showmap identities are fixed",
        )

        inputs = raw["inputs"]
        orderings = raw["round_orderings"]
        first_order = orderings[0]
        cyclic = (
            len(inputs) == 20
            and len(orderings) == raw["rounds"] == 3
            and set(first_order) == set(inputs)
            and all(
                ordering == first_order[offset:] + first_order[:offset]
                for offset, ordering in enumerate(orderings)
            )
        )
        check(cyclic, "F306 preserves three complete cyclic round orderings")

        selected_sets: dict[str, set[int]] = {}
        unstable: dict[str, tuple[int, list[int]]] = {}
        status_counts: dict[str, int] = {}
        rows_valid = True
        for name, row in inputs.items():
            replicas = row["replicas"]
            replica_sets: list[set[int]] = []
            replica_counts: list[int] = []
            if len(replicas) != 3:
                rows_valid = False
            for replica in replicas:
                edges = replica["edges"]
                edge_set = set(edges)
                rows_valid &= (
                    edges == sorted(edge_set)
                    and replica["edge_count"] == len(edge_set)
                    and replica["status"] == "ok"
                )
                replica_sets.append(edge_set)
                replica_counts.append(len(edge_set))
                status = replica["status"]
                status_counts[status] = status_counts.get(status, 0) + 1
            union = set().union(*replica_sets)
            intersection = set(replica_sets[0])
            for edge_set in replica_sets[1:]:
                intersection.intersection_update(edge_set)
            selected = set(row["selected_edges"])
            event_count = len(union - intersection)
            rows_valid &= (
                raw["stability_policy"] == "intersection"
                and selected == intersection
                and row["selected_edges"] == sorted(selected)
                and row["selected_edge_count"] == len(selected)
                and row["intersection_edge_count"] == len(intersection)
                and row["union_edge_count"] == len(union)
                and row["unstable_edges"] == event_count
            )
            selected_sets[name] = selected
            if event_count:
                unstable[name] = (event_count, replica_counts)
        check(
            rows_valid and status_counts == {"ok": 60},
            "F306 replica maps independently reproduce selected edge sets",
        )

        summary_unstable = {
            row["input"]: (row["unstable_edges"], row["replica_edge_counts"])
            for row in summary["unstable_inputs"]
        }
        unstable_events = sum(value[0] for value in unstable.values())
        check(
            unstable == summary_unstable
            and len(unstable) == summary["unstable_input_count"] == 11
            and unstable_events == summary["unstable_edge_events"] == 46
            and not summary["strict_stability_passed"],
            "F306 drift ledger recomputes 11 inputs and 46 unstable events",
        )

        baseline = selected_sets[raw["seed"]]
        baseline_row = inputs[raw["seed"]]
        novel_sets = [edges - baseline for edges in selected_sets.values()]
        novel_union = set().union(*novel_sets)
        landing_hits = sum(bool(edges) for edges in novel_sets)
        nominal = summary["strategies"]["nominal"]
        check(
            len(baseline) == summary["baseline_selected_edges"] == 1018
            and baseline_row["intersection_edge_count"]
            == summary["baseline_intersection_edges"]
            == 1018
            and baseline_row["union_edge_count"]
            == summary["baseline_union_edges"]
            == 1020
            and nominal["outputs"] == len(selected_sets) == 20
            and nominal["outputs_with_seed_novel_edges"] == landing_hits == 19
            and nominal["landing_rate_ppm"] == 950_000
            and nominal["novel_edge_union"] == len(novel_union) == 1378
            and nominal["exclusive_novel_edges"] == len(novel_union),
            "F306 baseline, landing, union, and single-label exclusivity recompute",
        )

        probe = summary["oracle_probe"]
        observations = sum(status_counts.values())
        check(
            observations == summary["campaign_observations"] == 60
            and summary["compatibility_probe_observations"] == 2
            and summary["total_oracle_observations"] == 62
            and summary["showmap_statuses"] == status_counts
            and summary["oracle_mode"] == "one-shot"
            and summary["oracle_fallbacks"] == 1
            and summary["oracle_restarts"] == 0
            and probe
            == {
                "isolated_edges": 1019,
                "isolated_status": "ok",
                "result": "status-mismatch+edge-set-mismatch",
                "streaming_edges": 933,
                "streaming_status": "timeout",
                "streaming_status_detail": 0,
            },
            "F306 accounts for all 60 campaign and two probe observations",
        )
        check(
            "do not establish a solver-strategy speedup" in readme
            and summary["candidate_inputs"] == 20
            and summary["unique_measured_inputs"] == 20
            and summary["round_delay_ms"] == raw["round_delay_ms"] == 1000,
            "F306 evidence records protocol bounds and the no-speedup claim",
        )
    except (
        OSError,
        IndexError,
        KeyError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ) as error:
        check(False, f"F306 evidence verification: {error}")


