                        math.isclose(summary["minimum_us"], min(samples)),
                        math.isclose(summary["median_us"], statistics.median(samples)),
                        math.isclose(summary["mean_us"], statistics.fmean(samples)),
                        math.isclose(summary["p95_us"], percentile(samples, 0.95)),
                        math.isclose(summary["maximum_us"], max(samples)),
