def verify_f342_evidence() -> None:
    root = CODEX / "evidence/f342-public-provenance-intersection-2026-08-10"
    expected_paths = {
        "README.md",
        "benchmark_provenance_intersection.py",
        "checks.txt",
        "directed-tests.log",
        "full-tests.log",
        "integration-tests.log",
        "provenance-intersection-cost.json",
        "provenance-intersection-cost.log",
        "provenance-intersection-mpi.json",
        "provenance-intersection-mpi.log",
        "run_provenance_intersection_mpi.py",
    }
    try:
        manifest_lines = (
            (root / "SHA256SUMS.txt").read_text(encoding="ascii").splitlines()
        )
        manifest_paths: set[str] = set()
        mismatches: list[str] = []
        for line in manifest_lines:
            expected_hash, relative = line.split("  ", 1)
            if relative in manifest_paths:
                mismatches.append(f"duplicate:{relative}")
                continue
            manifest_paths.add(relative)
            target = (root / relative).resolve()
            if root.resolve() not in target.parents or not target.is_file():
                mismatches.append(f"invalid:{relative}")
                continue
            if hashlib.sha256(target.read_bytes()).hexdigest() != expected_hash:
                mismatches.append(relative)
        check(
            not mismatches and manifest_paths == expected_paths,
            "F342 evidence files match the complete SHA-256 manifest",
        )

        readme = (root / "README.md").read_text(encoding="utf-8")
        checks = (root / "checks.txt").read_text(encoding="utf-8")
        directed = (root / "directed-tests.log").read_text(encoding="utf-8")
        integration = (root / "integration-tests.log").read_text(encoding="utf-8")
        full = (root / "full-tests.log").read_text(encoding="utf-8")
        mpi_driver = (root / "run_provenance_intersection_mpi.py").read_text(
            encoding="utf-8"
        )
        cost_driver = (root / "benchmark_provenance_intersection.py").read_text(
            encoding="utf-8"
        )
        mpi = json.loads(
            (root / "provenance-intersection-mpi.json").read_text(encoding="utf-8")
        )
        cost = json.loads(
            (root / "provenance-intersection-cost.json").read_text(encoding="utf-8")
        )

        check(
            "rank-1 delay" in readme
            and "No real multi-host" in checks
            and "does not rehash every object" in checks
            and "does not invoke SymCC's solver" in mpi["proof_boundary"]
            and "not campaign throughput" in cost["proof_boundary"],
            "F342 evidence preserves injection, integrity, deployment, and uplift boundaries",
        )
        check(
            "49 passed, 40 subtests passed in 0.90s" in directed
            and "338 passed, 67 subtests passed in 16.58s" in integration
            and "731 passed, 87 subtests passed in 94.03s" in full
            and "directed lifecycle: 49 passed" in checks
            and "full warnings-as-errors Python: 731 passed" in checks,
            "F342 directed, related, and full regressions are recorded",
        )

        def owner(work_hash: str) -> int:
            scores = []
            for rank in (0, 1):
                material = (f"symcc-work-owner-v1\0{work_hash}\0{rank}").encode("ascii")
                score = int.from_bytes(hashlib.sha256(material).digest()[:16], "big")
                scores.append((score, -rank, rank))
            return max(scores)[2]

        expected_phantom = ""
        for index in range(10_000):
            candidate = hashlib.sha256(
                f"F342-phantom-external-{index}".encode("ascii")
            ).hexdigest()
            if owner(candidate) == 1:
                expected_phantom = candidate
                break
        expected_generated = hashlib.sha256(b"F342-public-generated-object").hexdigest()
        case = mpi["case"]
        mpi_ok = (
            mpi["schema"] == "symcc-f342-public-provenance-intersection-mpi-v1"
            and mpi["actual_mpi_transport"] is True
            and mpi["actual_multi_host"] is False
            and mpi["synthetic_input_observer_target"] is True
            and mpi["deterministic_rank_delay_injection"] is True
            and mpi["configuration"]
            == {
                "masters": 2,
                "ranks": 7,
                "workers": 5,
            }
            and mpi["all_checks_passed"] is True
            and case["mode"] == "delayed-owner-phantom-external"
            and case["returncode"] == 0
            and 6.0 < case["elapsed_seconds"] < 20.0
            and case["master_one_delay_seconds"] == 6.0
            and case["phantom_owner"] == 1
            and case["phantom_external_hash"] == expected_phantom
            and case["generated_public_hash"] == expected_generated
            and case["observed_target_hashes"] == [expected_generated]
            and case["valid_public_objects"] == [expected_generated]
            and case["active_epoch_after_run"] is False
            and case["retired_epoch_count"] == 1
            and not case["staged_residue"]
            and len(case["checks"]) == 10
            and all(case["checks"].values())
            and "[Master] Observed 1 initial inputs" in case["output"]
            and "External input objects:      0" in case["output"]
            and "New interesting test cases:  1" in case["output"]
            and "acked=3/3" in case["output"]
            and "acked=2/2" in case["output"]
        )
        check(
            mpi_ok,
            "F342 real MPI phantom provenance and final namespace recompute exactly",
        )

        def nearest_percentile(values: list[float], fraction: float) -> float:
            ordered = sorted(values)
            index = max(
                0,
                min(
                    len(ordered) - 1,
                    math.ceil(fraction * len(ordered)) - 1,
                ),
            )
            return ordered[index]

        expected_configuration = {
            "filesystem": "local temporary directory",
            "objects": 4096,
            "order": "deterministically shuffled within every round",
            "phantom_external": 2048,
            "present_external": 2048,
            "retained_samples_per_mechanism": 30,
            "warmups_per_mechanism": 5,
        }
        cost_ok = (
            cost["schema"] == "symcc-f342-provenance-intersection-cost-v1"
            and cost["configuration"] == expected_configuration
            and cost["cardinalities"]
            == {
                "intersection_external": 2048,
                "intersection_generated": 2048,
                "intersection_public": 4096,
                "legacy_generated": 0,
                "legacy_public": 4096,
            }
            and cost["all_checks_passed"] is True
            and set(cost["raw_elapsed_us"]) == {"legacy", "intersection"}
            and len(cost["checks"]) == 7
            and all(cost["checks"].values())
        )
        for mechanism in ("legacy", "intersection"):
            samples = [float(value) for value in cost["raw_elapsed_us"][mechanism]]
            summary = cost["summaries"][mechanism]
            cost_ok = cost_ok and (
                len(samples) == 30
                and all(value > 0.0 for value in samples)
                and math.isclose(summary["median_us"], statistics.median(samples))
                and math.isclose(summary["p95_us"], nearest_percentile(samples, 0.95))
                and math.isclose(summary["minimum_us"], min(samples))
                and math.isclose(summary["maximum_us"], max(samples))
            )
        cost_ok = cost_ok and math.isclose(
            cost["elapsed_ratio_intersection_over_legacy"],
            cost["summaries"]["intersection"]["median_us"]
            / cost["summaries"]["legacy"]["median_us"],
        )
        check(
            cost_ok,
            "F342 60 interleaved samples and provenance cardinalities recompute exactly",
        )

        check(
            '"--oversubscribe"' in mpi_driver
            and '"-np",\n            "7"' in mpi_driver
            and "global_comm.Get_rank() == 1" in mpi_driver
            and "seed.unlink()" in mpi_driver
            and "_rendezvous_work_owner" in mpi_driver
            and "runner._count_public_corpus_objects" in cost_driver
            and "def _legacy_count" in cost_driver
            and "random.Random(342)" in cost_driver,
            "F342 drivers expose delay injection and compare the production path",
        )

        if REPOSITORY_CONTEXT:
            production = (REPO / "util/mpi_concolic_execution.py").read_text(
                encoding="utf-8"
            )
            lifecycle_tests = (REPO / "test/test_mpi_lifecycle.py").read_text(
                encoding="utf-8"
            )
            config = (REPO / "docs/Configuration.txt").read_text(encoding="utf-8")
            report = (
                CODEX / "research-progress/"
                "Public_Provenance_Intersection_F342_2026-08-10.md"
            ).read_text(encoding="utf-8")
            counter_start = production.index("class _CorpusProvenanceCounts")
            counter_end = production.index(
                "\ndef _regular_file_identity", counter_start
            )
            counter = production[counter_start:counter_end]
            scan_start = production.index("def _count_public_corpus_objects")
            scan_end = production.index("\ndef _stage_worker_outputs", scan_start)
            scan = production[scan_start:scan_end]
            master_start = production.index("def master_loop")
            master_end = production.index("def worker_loop", master_start)
            master = production[master_start:master_end]
            public_increment = scan.index("public += 1")
            membership = scan.index("if entry.name in external_hashes")
            external_increment = scan.index("external += 1")
            check(
                "@dataclass(frozen=True)"
                in production[max(0, counter_start - 30) : counter_end]
                and "return self.public - self.external" in counter
                and "with os.scandir(shared_dir) as entries:" in scan
                and "_normalize_work_hash(entry.name)" in scan
                and "entry.stat(follow_symlinks=False)" in scan
                and "stat.S_ISREG(metadata.st_mode)" in scan
                and public_increment < membership < external_increment
                and "listdir" not in scan,
                "F342 final scan computes public and external intersection in one no-follow pass",
            )
            check(
                "corpus_counts = _count_public_corpus_objects(" in master
                and "shared_dir, external_hashes" in master
                and "external_input_count = corpus_counts.external" in master
                and "actual_unique = corpus_counts.generated" in master
                and "Observed {initial_seed_count} initial inputs" in master
                and "len(external_hashes)"
                not in master[master.index("# --- Print final summary") :],
                "F342 root statistics use present-external rather than observed cardinality",
            )
            check(
                "test_public_corpus_accounting_intersects_external_provenance"
                in lifecycle_tests
                and "phantom_hash" in lifecycle_tests
                and "self.assertNotEqual(" in lifecycle_tests
                and "public intersection observed-external" in config
                and "P ∩ O" in report
                and "P \\ E" in report,
                "F342 counterexample, invariant, configuration, and report are wired",
            )
        else:
            skip("F342 production wiring check needs repository context")
    except (IndexError, KeyError, OSError, TypeError, ValueError) as error:
        check(False, f"F342 evidence verification: {error}")


