def verify_f385_evidence() -> None:
    root = CODEX / "evidence/f385-byte-lane-writer-graph-2026-08-13"

    def artifact_summary(
        artifact: dict[str, object],
    ) -> tuple[
        int,
        int,
        int,
        int,
        set[tuple[tuple[int, str, int, int], ...]],
    ]:
        functions = artifact["functions"]
        assert isinstance(functions, dict)
        graph_count = 0
        phi_count = 0
        poison_bound_stores = 0
        lane_sets: set[tuple[tuple[int, str, int, int], ...]] = set()
        for function in functions.values():
            assert isinstance(function, dict)
            phi_count += len(function.get("byte_lane_memory_definedness_phis", []))
            graph_store_ids: set[str] = set()
            for contract in function.get("byte_lane_memory_definedness", []):
                if contract.get("writer_graph") is not True:
                    continue
                graph_count += 1
                lanes: list[tuple[int, str, int, int]] = []
                for lane in contract.get("lanes", []):
                    source = str(lane.get("source", ""))
                    store_id = str(lane.get("store", ""))
                    if source == "store":
                        graph_store_ids.add(store_id)
                    lanes.append(
                        (
                            int(lane.get("lane", -1)),
                            source,
                            int(lane.get("store_byte", -1)),
                            int(lane.get("store_bytes", 0)),
                        )
                    )
                lane_sets.add(tuple(sorted(lanes)))
            for instructions in function["blocks"].values():
                for instruction in instructions:
                    if (
                        instruction.get("op") == "store"
                        and str(instruction.get("byte_lane_store", ""))
                        in graph_store_ids
                        and instruction.get("byte_lane_poison_source")
                    ):
                        poison_bound_stores += 1
        return (
            len(functions),
            graph_count,
            phi_count,
            poison_bound_stores,
            lane_sets,
        )

