def verify_package() -> None:
    path = CODEX / "SymCC_Project_Report_2026-07-30-reviewed.zip"
    prefix = "symcc-report-codex/"
    try:
        with zipfile.ZipFile(path) as archive:
            check(archive.testzip() is None, "reviewed ZIP members pass CRC")
            raw = archive.read(prefix + "PACKAGE_MANIFEST.sha256").decode("utf-8")
            mismatches: list[str] = []
            for line in raw.splitlines():
                expected, rel = line.split("  ", 1)
                actual = hashlib.sha256(archive.read(prefix + rel)).hexdigest()
                if actual != expected:
                    mismatches.append(rel)
            check(not mismatches, "reviewed ZIP matches its SHA-256 content manifest")
    except (OSError, KeyError, ValueError, zipfile.BadZipFile) as error:
        check(False, f"reviewed ZIP structural verification: {error}")


def verify_f429_package() -> None:
    path = CODEX / "SymCC_F429_QFBV_Artifact_Lifecycle_2026-08-17.zip"
    prefix = "symcc-f429-artifact-lifecycle/"
    try:
        with zipfile.ZipFile(path) as archive:
            check(archive.testzip() is None, "F429 delivery ZIP members pass CRC")
            raw = archive.read(prefix + "PACKAGE_MANIFEST.sha256").decode("ascii")
            manifest_paths: set[str] = set()
            mismatches: list[str] = []
            for line in raw.splitlines():
                expected, relative = line.split("  ", 1)
                if relative in manifest_paths:
                    mismatches.append(f"duplicate:{relative}")
                    continue
                manifest_paths.add(relative)
                try:
                    payload = archive.read(prefix + relative)
                except KeyError:
                    mismatches.append(f"missing:{relative}")
                    continue
                if hashlib.sha256(payload).hexdigest() != expected:
                    mismatches.append(relative)
            required = {
                "benchmark/check_qfbv_artifact_lifecycle_oracles.py",
                "docs/Configuration.txt",
                "docs/Testing.txt",
                ("docs/codex/diagrams/solver-context/f429_qfbv_artifact_lifecycle.png"),
                ("docs/codex/diagrams/solver-context/f429_qfbv_artifact_lifecycle.svg"),
                (
                    "docs/codex/evidence/f429-qfbv-artifact-lifecycle-"
                    "2026-08-17/SHA256SUMS.txt"
                ),
                (
                    "docs/codex/research-progress/"
                    "Lease_Fenced_QFBV_Artifact_Lifecycle_F429_2026-08-17.md"
                ),
                "test/test_qfbv_artifact_lifecycle.py",
                "util/qfbv_artifact_lifecycle.py",
                "util/symcc_query_service.py",
            }
            check(
                not mismatches and required <= manifest_paths,
                "F429 delivery ZIP matches its complete source/evidence manifest",
            )
    except (OSError, KeyError, UnicodeError, ValueError, zipfile.BadZipFile) as error:
        check(False, f"F429 delivery ZIP verification: {error}")


